const loadSwiggyData = async () => {
    const res = await fetch(API_URL);
    const json = await res.json();
    const cards = json.data.cards;
    const deliveryBox = document.getElementById("delivery-grid");
    deliveryBox.innerHTML = "";

    for (let i = 0; i < cards.length; i++) {
        if (cards[i].card.card.id === "top_brands_for_you") {
            const onlineDelivery = cards[i].card.card.gridElements.infoWithStyle.restaurants;
            onlineDelivery.forEach(res => {
                const info = res.info;
                const resImage = foodImages[info.name] || foodImages["default"];
                deliveryBox.innerHTML += `
                    <div class="res-card">
                        <img src="${resImage}" alt="${info.name}">
                        <div class="res-info">
                            <h3>${info.name}</h3>
                            <p>★ ${info.avgRating} • ${info.sla.deliveryTime} mins</p>
                            <p>${info.cuisines.join(", ")}</p>
                            <p style="color: #fc8019; font-weight: 500; font-size: 13px; margin-top: 2px;">📍 ${info.areaName}</p>
                        </div>
                    </div>`;
            });
        }
    }
};
loadSwiggyData();
